UPDATE public.productos SET
  ficha_pdf = '/assets/productos/fichas/fisher-paykel-healthcare/neopuff-t-piece-rd900-series-specification-sheet-pm-617631.pdf',
  descripcion_larga_es = $d$El Neopuff de Fisher & Paykel es un reanimador neonatal en T que entrega presión inspiratoria pico (PIP) y PEEP de forma controlada y constante, con manómetro preciso y de fácil lectura, control de PIP y válvula de alivio de presión máxima. Admite oxígeno del 21 % al 100 % desde caudalímetros o mezclador de gas, con flujo de entrada de 5 a 15 L/min. La unidad pesa 1,9 kg (250 x 200 x 104 mm) y su manómetro cubre de -10 a 80 cmH₂O con precisión de ±2 % del fondo de escala.$d$,
  descripcion_larga_en = $d$The Fisher & Paykel Neopuff is a neonatal T-piece resuscitator that delivers controlled, consistent peak inspiratory pressure (PIP) and PEEP, with an accurate, easy-to-read manometer, PIP control and maximum pressure relief valve. It accepts oxygen from 21% to 100% from flowmeters or a gas blender, with input flow of 5 to 15 L/min. The unit weighs 1.9 kg (250 x 200 x 104 mm) and its manometer covers -10 to 80 cmH₂O with ±2% full-scale accuracy.$d$,
  especificaciones = $j$[{"clave":"Modelo","grupo":"Identificación","valor":"Neopuff RD900 series"},{"clave":"Fabricante","grupo":"Identificación","valor":"Fisher & Paykel Healthcare"},{"clave":"Dimensiones / peso","grupo":"Dimensiones","valor":"250 x 200 x 104 mm; 1,9 kg"},{"clave":"Manómetro","grupo":"Rendimiento","valor":"-10 a 80 cmH₂O, ±2 % del fondo de escala"},{"clave":"Flujo de entrada","grupo":"Rendimiento","valor":"5 - 15 L/min"},{"clave":"Alivio de presión máxima","grupo":"Rendimiento","valor":"5 - 70 cmH₂O (ajuste de fábrica 40 cmH₂O)"},{"clave":"Oxígeno","grupo":"Rendimiento","valor":"21 - 100 %"},{"clave":"Clasificación","grupo":"Regulatorio","valor":"Clase IIb (UE y Australia), Clase II (EE. UU.); origen Nueva Zelanda"}]$j$::jsonb,
  atributos = COALESCE(atributos, '{}'::jsonb) || $j${"beneficios_es":["Presiones PIP y PEEP más controladas y consistentes que con bolsas autoinflables, según el fabricante.","Manómetro de -10 a 80 cmH₂O y válvula de alivio de presión máxima de fábrica en 40 cmH₂O.","Oxígeno del 21 % al 100 % con flujo de entrada de 5 a 15 L/min; unidad ligera de 1,9 kg."],"beneficios_en":["More controlled and consistent PIP and PEEP than self-inflating bags, per the manufacturer.","Manometer from -10 to 80 cmH₂O and maximum pressure relief valve factory-set at 40 cmH₂O.","Oxygen from 21% to 100% with 5 to 15 L/min input flow; light 1.9 kg unit."],"valor_es":"Un reanimador neonatal en T con control preciso de presión, usado en sala de partos, UCIN y transporte, con documentación oficial de Fisher & Paykel.","valor_en":"A neonatal T-piece resuscitator with precise pressure control, used in the delivery room, NICU and transport, with official Fisher & Paykel documentation.","preguntas_frecuentes_es":[{"q":"¿Qué ventaja tiene un reanimador en T frente a una bolsa?","a":"Las guías internacionales de reanimación neonatal recomiendan el uso de un reanimador en T cuando hay fuente de gas; según Fisher & Paykel, entrega PIP y PEEP más controlados y consistentes que las bolsas autoinflables o de flujo."},{"q":"¿Qué flujo de gas necesita?","a":"Un flujo de entrada de 5 a 15 L/min; el fabricante recomienda gas médico mezclado de aire y oxígeno."},{"q":"¿Qué incluye la caja?","a":"Unidad Neopuff, línea de gas, adaptador de entrada de gas, pulmón de prueba, tapa de repuesto de la válvula de presión máxima e instrucciones de uso."},{"q":"¿Dónde descargo la ficha técnica de Resucitador Neonatal Neopuff Fisher & Paykel?","a":"En esta página, con el botón «Descargar ficha técnica»: es el PDF oficial de Fisher & Paykel Healthcare (en inglés)."}],"preguntas_frecuentes_en":[{"q":"What advantage does a T-piece resuscitator have over a bag?","a":"International neonatal resuscitation guidelines recommend a T-piece resuscitator when a gas source is available; per Fisher & Paykel it delivers more controlled and consistent PIP and PEEP than self-inflating or flow-inflating bags."},{"q":"What gas flow does it need?","a":"An input flow of 5 to 15 L/min; the manufacturer recommends blended medical-grade air and oxygen."},{"q":"What is in the box?","a":"Neopuff unit, gas supply line, gas inlet adaptor, test lung, spare maximum pressure relief cap and user instructions."},{"q":"Where can I download the Fisher & Paykel Neonatal Resuscitator Neopuff datasheet?","a":"On this page, with the “Download datasheet” button: it is the official Fisher & Paykel Healthcare PDF (in English)."}],"seo_keywords_es":["reanimador neonatal en T","Neopuff Fisher & Paykel","reanimación neonatal en sala de partos","reanimador con PEEP controlado","equipo de reanimación neonatal Colombia","ficha técnica Neopuff RD900"],"seo_keywords_en":["neonatal T-piece resuscitator","Fisher & Paykel Neopuff","neonatal resuscitation delivery room","resuscitator with controlled PEEP","neonatal resuscitation equipment Colombia","Neopuff RD900 datasheet"],"ficha_fabricante":{"fabricante":"Fisher & Paykel Healthcare","idioma":"en","url_origen":"https://resources.fphcare.com/content/neopuff-t-piece-rd900-series-specification-sheet-pm-617631.pdf","descargada":"2026-10-02"}}$j$::jsonb
WHERE slug = 'resucitador-neonatal-neopuff-fisher-paykel';

UPDATE public.productos SET
  ficha_pdf = '/assets/productos/fichas/fisher-paykel-healthcare/airvo-2-specification-sheet-interface-accessories-pm-185045320.pdf',
  descripcion_larga_es = $d$El AIRVO 2 de Fisher & Paykel es un humidificador con generador de flujo integrado que entrega gases respiratorios calentados y humidificados a flujos de 2 a 60 L/min, a través de interfaces nasales, de traqueostomía o mascarillas con conector estándar de 22 mm. Cumple la norma ISO 8185:2007 de humidificación, ofrece modo estándar (10-60 L/min en pasos de 5) y modo Junior (2-25 L/min en pasos de 1), pesa 2,2 kg y mide 295 x 170 x 175 mm.$d$,
  descripcion_larga_en = $d$The Fisher & Paykel AIRVO 2 is a humidifier with integrated flow generator that delivers warmed and humidified respiratory gases at flows of 2 to 60 L/min, through nasal, tracheostomy or mask interfaces with a standard 22 mm taper. It complies with the ISO 8185:2007 humidification standard, offers a standard mode (10-60 L/min in 5 L/min steps) and a Junior mode (2-25 L/min in 1 L/min steps), weighs 2.2 kg and measures 295 x 170 x 175 mm.$d$,
  especificaciones = $j$[{"clave":"Modelo","grupo":"Identificación","valor":"AIRVO 2"},{"clave":"Fabricante","grupo":"Identificación","valor":"Fisher & Paykel Healthcare"},{"clave":"Flujo","grupo":"Rendimiento","valor":"2 - 60 L/min"},{"clave":"Humidificación","grupo":"Rendimiento","valor":"Cumple ISO 8185:2007"},{"clave":"Dimensiones / peso","grupo":"Dimensiones","valor":"295 x 170 x 175 mm; 2,2 kg (solo unidad)"},{"clave":"Alimentación","grupo":"Eléctrico","valor":"100-115 V ~ 2,2 A / 220-240 V ~ 1,8 A, 50-60 Hz"},{"clave":"Entorno","grupo":"Uso","valor":"Hospitales y centros de larga estancia"}]$j$::jsonb,
  atributos = COALESCE(atributos, '{}'::jsonb) || $j${"beneficios_es":["Flujo de 2 a 60 L/min con humidificación integrada, para pacientes con respiración espontánea.","Compatible con cánulas nasales y traqueostomía Optiflow+ y mascarillas de 22 mm.","Compacto: 2,2 kg y 295 x 170 x 175 mm, con accesorios como soporte de poste y soporte de cilindro de oxígeno."],"beneficios_en":["Flow from 2 to 60 L/min with integrated humidification, for spontaneously breathing patients.","Compatible with Optiflow+ nasal and tracheostomy interfaces and 22 mm masks.","Compact: 2.2 kg and 295 x 170 x 175 mm, with accessories such as a pole stand and oxygen bottle holder."],"valor_es":"Un sistema de alto flujo nasal con humidificador integrado para hospitales y cuidados de larga estancia, con documentación oficial de Fisher & Paykel.","valor_en":"A nasal high flow system with integrated humidifier for hospitals and long-term care, with official Fisher & Paykel documentation.","preguntas_frecuentes_es":[{"q":"¿Para qué pacientes está indicado?","a":"Para pacientes con respiración espontánea que se benefician de gases calentados y humidificados a alto flujo, incluidos pacientes con vía aérea superior derivada, en hospitales y centros de larga estancia, según la ficha."},{"q":"¿Qué rango de flujo tiene?","a":"De 2 a 60 L/min según la interfaz; el modo estándar usa 10-60 L/min y el modo Junior 2-25 L/min."},{"q":"¿Qué accesorios admite?","a":"Kit de desinfección, filtros, kit de tubo y cámara, soporte de poste, kit de montaje UPS, soporte de cilindro de oxígeno y kit de entrada de oxígeno."},{"q":"¿Dónde descargo la ficha técnica de Sistema de Alto Flujo Airvo 2 Fisher & Paykel?","a":"En esta página, con el botón «Descargar ficha técnica»: es el PDF oficial de Fisher & Paykel Healthcare (en inglés)."}],"preguntas_frecuentes_en":[{"q":"Which patients is it indicated for?","a":"Spontaneously breathing patients who benefit from warmed, humidified high-flow gases, including those with bypassed upper airways, in hospitals and long-term care, per the datasheet."},{"q":"What flow range does it have?","a":"From 2 to 60 L/min depending on the interface; standard mode uses 10-60 L/min and Junior mode 2-25 L/min."},{"q":"Which accessories does it support?","a":"Disinfection kit, filters, tube and chamber kit, pole stand, UPS mounting kit, oxygen bottle holder and oxygen inlet kit."},{"q":"Where can I download the Fisher & Paykel High-Flow System Airvo 2 datasheet?","a":"On this page, with the “Download datasheet” button: it is the official Fisher & Paykel Healthcare PDF (in English)."}],"seo_keywords_es":["AIRVO 2","sistema de alto flujo nasal","cánula de alto flujo Optiflow","humidificador con generador de flujo","oxigenoterapia de alto flujo Colombia","ficha técnica AIRVO 2"],"seo_keywords_en":["AIRVO 2","nasal high flow system","Optiflow high flow cannula","humidifier with flow generator","high flow oxygen therapy Colombia","AIRVO 2 datasheet"],"ficha_fabricante":{"fabricante":"Fisher & Paykel Healthcare","idioma":"en","url_origen":"https://resources.fphcare.com/content/airvo-2-specification-sheet-interface-accessories-pm-185045320.pdf","descargada":"2026-10-02"}}$j$::jsonb
WHERE slug = 'sistema-de-alto-flujo-airvo-2-fisher-paykel';

UPDATE public.productos SET
  ficha_pdf = '/assets/productos/fichas/fisher-paykel-healthcare/oj2-spec-sheet-north-america-pm-632890.pdf',
  descripcion_larga_es = $d$La interfaz nasal Optiflow Junior 2 de Fisher & Paykel entrega terapia de alto flujo nasal calentado y humidificado a pacientes con respiración espontánea. Se ofrece en tallas XS a XXL (6,7 g a 28,2 g por kit), con conector easy-click, de un solo paciente y uso de hasta 14 días, vida útil de 5 años y sin látex natural, PVC ni ftalatos. Se vende en cajas de 20 o 10 unidades.$d$,
  descripcion_larga_en = $d$The Fisher & Paykel Optiflow Junior 2 nasal interface delivers heated and humidified nasal high flow therapy to spontaneously breathing patients. It comes in sizes XS to XXL (6.7 g to 28.2 g per kit), with an easy-click connector, single patient use for up to 14 days, a 5-year shelf life and no natural latex, PVC or phthalates. It is sold in boxes of 20 or 10.$d$,
  especificaciones = $j$[{"clave":"Modelo","grupo":"Identificación","valor":"Optiflow Junior 2 (OJR410-OJR520)"},{"clave":"Fabricante","grupo":"Identificación","valor":"Fisher & Paykel Healthcare"},{"clave":"Duración","grupo":"Uso","valor":"14 días, un solo paciente"},{"clave":"Vida útil","grupo":"Almacenamiento","valor":"5 años; -10 a +50 °C"},{"clave":"Cantidad","grupo":"Presentación","valor":"Caja de 20 o de 10"},{"clave":"Sin","grupo":"Materiales","valor":"Látex natural, PVC ni ftalatos"}]$j$::jsonb,
  atributos = COALESCE(atributos, '{}'::jsonb) || $j${"beneficios_es":["Seis tallas (XS a XXL) para ajustar la interfaz a lactantes y niños.","Conector easy-click, uso de hasta 14 días y vida útil de 5 años.","Sin látex natural, PVC ni ftalatos (DEHP, DBP, BBP)."],"beneficios_en":["Six sizes (XS to XXL) to fit the interface to infants and children.","Easy-click connector, up to 14 days of use and 5-year shelf life.","No natural latex, PVC or phthalates (DEHP, DBP, BBP)."],"valor_es":"Una interfaz de alto flujo nasal pediátrica en seis tallas, con especificaciones oficiales de Fisher & Paykel.","valor_en":"A paediatric nasal high flow interface in six sizes, with official Fisher & Paykel specifications.","preguntas_frecuentes_es":[{"q":"¿Qué tallas existen?","a":"XS, S, M, L, XL y XXL, con referencias OJR410, OJR412, OJR414, OJR416, OJR418 y OJR520."},{"q":"¿Cuánto tiempo se puede usar?","a":"Es de un solo paciente y la duración de uso indicada es de 14 días."},{"q":"¿Con qué sistemas se usa?","a":"Con un sistema de terapia de alto flujo nasal, por ejemplo equipos con humidificación F&P 950 o AIRVO, según la ficha."},{"q":"¿Dónde descargo la ficha técnica de Interfaz Nasal Optiflow Junior 2 Fisher & Paykel?","a":"En esta página, con el botón «Descargar ficha técnica»: es el PDF oficial de Fisher & Paykel Healthcare (en inglés)."}],"preguntas_frecuentes_en":[{"q":"Which sizes are available?","a":"XS, S, M, L, XL and XXL, with codes OJR410, OJR412, OJR414, OJR416, OJR418 and OJR520."},{"q":"How long can it be used?","a":"It is single-patient use with a stated duration of 14 days."},{"q":"Which systems is it used with?","a":"With a nasal high flow therapy system, for example units with F&P 950 or AIRVO humidification, per the datasheet."},{"q":"Where can I download the Fisher & Paykel Optiflow Junior 2 Nasal Interface datasheet?","a":"On this page, with the “Download datasheet” button: it is the official Fisher & Paykel Healthcare PDF (in English)."}],"seo_keywords_es":["interfaz nasal Optiflow Junior 2","cánula de alto flujo pediátrica","alto flujo nasal neonatal","interfaz Fisher & Paykel","terapia de alto flujo pediátrica Colombia","ficha técnica Optiflow Junior 2"],"seo_keywords_en":["Optiflow Junior 2 nasal interface","paediatric high flow cannula","neonatal nasal high flow","Fisher & Paykel interface","paediatric high flow therapy Colombia","Optiflow Junior 2 datasheet"],"ficha_fabricante":{"fabricante":"Fisher & Paykel Healthcare","idioma":"en","url_origen":"https://resources.fphcare.com/content/oj2-spec-sheet-north-america-pm-632890.pdf","descargada":"2026-10-02"}}$j$::jsonb
WHERE slug = 'interfaz-nasal-optiflow-junior-2-fisher-paykel';

UPDATE public.productos SET
  ficha_pdf = '/assets/productos/fichas/fisher-paykel-healthcare/oj2-blender-kit-spec-sheet-north-america-pm-632888.pdf',
  descripcion_larga_es = $d$El kit de blender de transición Optiflow Junior 2 de Fisher & Paykel permite usar la interfaz Optiflow Junior 2 con circuitos respiratorios F&P aprobados cuando se conecta a un mezclador, para administrar terapia de alto flujo nasal calentado y humidificado sin cambiar el circuito existente. Incluye interfaz, colector de alivio de presión y adaptador, con presión de alivio nominal de 40 cmH₂O; se presenta en cajas de 5 en tallas XS a XL.$d$,
  descripcion_larga_en = $d$The Fisher & Paykel Optiflow Junior 2 Blender Transition Kit allows the Optiflow Junior 2 interface to be used with approved F&P breathing circuits when connected to a blender, delivering heated and humidified nasal high flow therapy without changing the existing circuit. It includes the interface, a pressure relief manifold and an adapter, with a nominal relief pressure of 40 cmH₂O; it comes in boxes of 5 in sizes XS to XL.$d$,
  especificaciones = $j$[{"clave":"Modelo","grupo":"Identificación","valor":"Optiflow Junior 2 Blender Transition Kit (OJR41xB)"},{"clave":"Fabricante","grupo":"Identificación","valor":"Fisher & Paykel Healthcare"},{"clave":"Presión de alivio nominal","grupo":"Seguridad","valor":"40 cmH₂O"},{"clave":"Cantidad","grupo":"Presentación","valor":"Caja de 5"},{"clave":"Duración","grupo":"Uso","valor":"14 días, un solo paciente"},{"clave":"Vida útil","grupo":"Almacenamiento","valor":"5 años"}]$j$::jsonb,
  atributos = COALESCE(atributos, '{}'::jsonb) || $j${"beneficios_es":["Permite pasar a alto flujo nasal sin reemplazar el circuito existente.","Colector de alivio de presión con presión de alivio nominal de 40 cmH₂O.","Cajas de 5 en tallas XS a XL; hasta 14 días de uso por paciente."],"beneficios_en":["Lets you switch to nasal high flow without replacing the existing circuit.","Pressure relief manifold with 40 cmH₂O nominal relief pressure.","Boxes of 5 in sizes XS to XL; up to 14 days of use per patient."],"valor_es":"Un kit de transición para ofrecer alto flujo nasal con el circuito y mezclador ya instalados, con ficha oficial de Fisher & Paykel.","valor_en":"A transition kit to offer nasal high flow with the circuit and blender already in place, with official Fisher & Paykel datasheet.","preguntas_frecuentes_es":[{"q":"¿Qué incluye el kit?","a":"Interfaz nasal Optiflow Junior 2, colector de alivio de presión, adaptador e instrucciones de uso."},{"q":"¿Qué referencias tiene?","a":"OJR410B, OJR412B, OJR414B, OJR416B y OJR418B según la talla."},{"q":"¿Cuál es la presión de alivio?","a":"Presión de alivio nominal de 40 cmH₂O."},{"q":"¿Dónde descargo la ficha técnica de Kit de Blender Para Transición Fisher & Paykel?","a":"En esta página, con el botón «Descargar ficha técnica»: es el PDF oficial de Fisher & Paykel Healthcare (en inglés)."}],"preguntas_frecuentes_en":[{"q":"What does the kit include?","a":"Optiflow Junior 2 nasal interface, pressure relief manifold, adapter and user instructions."},{"q":"Which codes does it have?","a":"OJR410B, OJR412B, OJR414B, OJR416B and OJR418B depending on size."},{"q":"What is the relief pressure?","a":"Nominal relief pressure of 40 cmH₂O."},{"q":"Where can I download the Blender Transition Kit Fisher & Paykel datasheet?","a":"On this page, with the “Download datasheet” button: it is the official Fisher & Paykel Healthcare PDF (in English)."}],"seo_keywords_es":["kit de blender Optiflow Junior 2","transición de CPAP a alto flujo","alto flujo nasal neonatal","kit Fisher & Paykel","alto flujo neonatal Colombia","ficha técnica kit blender OJ2"],"seo_keywords_en":["Optiflow Junior 2 blender kit","CPAP to high flow transition","neonatal nasal high flow","Fisher & Paykel kit","neonatal high flow Colombia","OJ2 blender kit datasheet"],"ficha_fabricante":{"fabricante":"Fisher & Paykel Healthcare","idioma":"en","url_origen":"https://resources.fphcare.com/content/oj2-blender-kit-spec-sheet-north-america-pm-632888.pdf","descargada":"2026-10-02"}}$j$::jsonb
WHERE slug = 'kit-de-blender-para-transicion-fisher-paykel';

UPDATE public.productos SET
  ficha_pdf = '/assets/productos/fichas/fisher-paykel-healthcare/oj2-spec-sheet-north-america-pm-632890.pdf',
  descripcion_larga_es = $d$Los Wigglepads de Fisher & Paykel son el accesorio que sustituye las cintas adhesivas para fijar las cánulas de alto flujo de la serie Optiflow Junior. La ficha oficial de la interfaz Optiflow Junior 2 los lista como repuestos compatibles (Wigglepads 2, referencias WJR110, WJR112 y WJR114), en cajas de 40 unidades (2 paquetes de 20).$d$,
  descripcion_larga_en = $d$Fisher & Paykel Wigglepads are the accessory that replaces adhesive tape to secure Optiflow Junior series high flow cannulas. The official Optiflow Junior 2 interface datasheet lists them as compatible spares (Wigglepads 2, codes WJR110, WJR112 and WJR114), in cases of 40 (2 packs of 20).$d$,
  especificaciones = $j$[{"clave":"Fabricante","grupo":"Identificación","valor":"Fisher & Paykel Healthcare"},{"clave":"Interfaz","grupo":"Compatibilidad","valor":"Optiflow Junior 2 (ficha oficial adjunta)"},{"clave":"Wigglepads 2","grupo":"Referencias","valor":"WJR110, WJR112, WJR114"},{"clave":"Caja","grupo":"Presentación","valor":"40 unidades (2 paquetes de 20)"}]$j$::jsonb,
  atributos = COALESCE(atributos, '{}'::jsonb) || $j${"beneficios_es":["Reemplazan las cintas adhesivas en la fijación de la cánula Optiflow Junior.","Listados como repuestos compatibles de la interfaz Optiflow Junior 2.","Presentación en caja de 40 unidades (2 paquetes de 20)."],"beneficios_en":["Replace adhesive tape to secure the Optiflow Junior cannula.","Listed as compatible spares for the Optiflow Junior 2 interface.","Case of 40 (2 packs of 20)."],"valor_es":"Un accesorio de fijación para cánulas Optiflow Junior, referenciado en la ficha oficial de Fisher & Paykel.","valor_en":"A securing accessory for Optiflow Junior cannulas, referenced in the official Fisher & Paykel datasheet.","preguntas_frecuentes_es":[{"q":"¿Para qué sirven?","a":"Para fijar las cánulas de alto flujo de la serie Optiflow Junior en lugar de usar cintas adhesivas."},{"q":"¿Qué referencias figuran en la ficha?","a":"WJR110, WJR112 y WJR114 (Wigglepads 2)."},{"q":"¿Cómo se presentan?","a":"En caja de 40 unidades (2 paquetes de 20)."},{"q":"¿Dónde descargo la ficha técnica de Prematuro Wigglepads Ref OPT010 Fisher & Paykel?","a":"En esta página, con el botón «Descargar ficha técnica»: es el PDF oficial de Fisher & Paykel Healthcare (en inglés)."}],"preguntas_frecuentes_en":[{"q":"What are they for?","a":"To secure Optiflow Junior series high flow cannulas instead of using adhesive tape."},{"q":"Which codes appear in the datasheet?","a":"WJR110, WJR112 and WJR114 (Wigglepads 2)."},{"q":"How are they packed?","a":"In a case of 40 (2 packs of 20)."},{"q":"Where can I download the Prematuro Wigglepads Ref OPT010 Fisher & Paykel datasheet?","a":"On this page, with the “Download datasheet” button: it is the official Fisher & Paykel Healthcare PDF (in English)."}],"seo_keywords_es":["Wigglepads Fisher & Paykel","fijación de cánula Optiflow Junior","accesorio alto flujo neonatal","Wigglepads Optiflow","insumos neonatales Colombia","ficha técnica Optiflow Junior 2"],"seo_keywords_en":["Fisher & Paykel Wigglepads","Optiflow Junior cannula securement","neonatal high flow accessory","Optiflow Wigglepads","neonatal supplies Colombia","Optiflow Junior 2 datasheet"],"ficha_fabricante":{"fabricante":"Fisher & Paykel Healthcare","idioma":"en","url_origen":"https://resources.fphcare.com/content/oj2-spec-sheet-north-america-pm-632890.pdf","descargada":"2026-10-02"}}$j$::jsonb
WHERE slug = 'prematuro-wigglepads-ref-opt010-fisher-paykel';

UPDATE public.productos SET
  ficha_pdf = '/assets/productos/fichas/fisher-paykel-healthcare/bubble-cpap-system-ui-185042847.pdf',
  descripcion_larga_es = $d$El arnés para CPAP de burbuja forma parte de las interfaces de Fisher & Paykel diseñadas para ofrecer CPAP con el máximo confort al neonato y apoyar los cuidados centrados en el desarrollo. La ficha del fabricante es el manual de instrucciones del sistema Bubble CPAP BC151/BC161: CPAP medio de 3 a 10 cmH₂O, flujo de entrada de 4 a 15 L/min, uso en UCIN/UCIP en neonatos de hasta 10 kg, componentes de un solo uso y duración máxima de 7 días.$d$,
  descripcion_larga_en = $d$The bubble CPAP harness is part of the Fisher & Paykel interfaces designed to deliver CPAP with maximum comfort for the neonate and support developmental care. The manufacturer document is the Bubble CPAP System BC151/BC161 user instructions: mean CPAP of 3 to 10 cmH₂O, input flow of 4 to 15 L/min, for NICU/PICU use in neonates up to 10 kg, single-use components and a maximum use of 7 days.$d$,
  especificaciones = $j$[{"clave":"Fabricante","grupo":"Identificación","valor":"Fisher & Paykel Healthcare"},{"clave":"Documento","grupo":"Sistema","valor":"Instrucciones de uso Bubble CPAP BC151/BC161 (REF 185042847)"},{"clave":"CPAP medio","grupo":"Terapia","valor":"3 - 10 cmH₂O"},{"clave":"Flujo de entrada","grupo":"Terapia","valor":"4 - 15 L/min"},{"clave":"Duración / paciente","grupo":"Uso","valor":"Un solo paciente; máximo 7 días"}]$j$::jsonb,
  atributos = COALESCE(atributos, '{}'::jsonb) || $j${"beneficios_es":["Interfaz pensada para el confort del neonato y los cuidados centrados en el desarrollo.","Componente de un solo uso del sistema Bubble CPAP.","Documentado en las instrucciones oficiales del sistema."],"beneficios_en":["Interface designed for neonate comfort and developmental care.","Single-use component of the Bubble CPAP system.","Documented in the official system instructions."],"valor_es":"Un componente del sistema Bubble CPAP de Fisher & Paykel para soporte respiratorio neonatal, documentado en las instrucciones oficiales del sistema.","valor_en":"A component of the Fisher & Paykel Bubble CPAP system for neonatal respiratory support, documented in the official system instructions.","preguntas_frecuentes_es":[{"q":"¿Para qué pacientes es el sistema Bubble CPAP?","a":"Para neonatos y lactantes de hasta 10 kg que respiran espontáneamente y requieren CPAP, por ejemplo por prematuridad, en UCIN o UCIP, según las instrucciones del fabricante."},{"q":"¿Se puede reutilizar?","a":"No. Todos los componentes del sistema son de un solo paciente y el uso máximo indicado es de 7 días."},{"q":"¿Qué rango de CPAP maneja el sistema?","a":"CPAP medio de 3 a 10 cmH₂O con flujo de entrada de 4 a 15 L/min (inicial recomendado 6-8 L/min)."},{"q":"¿Dónde descargo la ficha técnica de Arnés Para CPAP de Burbuja Fisher & Paykel?","a":"En esta página, con el botón «Descargar ficha técnica»: es el PDF oficial de Fisher & Paykel Healthcare (en inglés)."}],"preguntas_frecuentes_en":[{"q":"Which patients is the Bubble CPAP system for?","a":"Spontaneously breathing neonates and infants up to 10 kg who need CPAP, for example due to prematurity, in NICU or PICU, per the manufacturer instructions."},{"q":"Can it be reused?","a":"No. All system components are single-patient use and the stated maximum use is 7 days."},{"q":"What CPAP range does the system provide?","a":"Mean CPAP of 3 to 10 cmH₂O with input flow of 4 to 15 L/min (recommended starting range 6-8 L/min)."},{"q":"Where can I download the Fisher & Paykel Bubble CPAP Harness datasheet?","a":"On this page, with the “Download datasheet” button: it is the official Fisher & Paykel Healthcare PDF (in English)."}],"seo_keywords_es":["arnés CPAP de burbuja","arnés Fisher & Paykel neonatal","CPAP neonatal","interfaz CPAP prematuros","insumos CPAP neonatal Colombia","instrucciones Bubble CPAP BC161"],"seo_keywords_en":["bubble CPAP harness","Fisher & Paykel neonatal harness","neonatal CPAP","preterm CPAP interface","neonatal CPAP supplies Colombia","Bubble CPAP BC161 instructions"],"ficha_fabricante":{"fabricante":"Fisher & Paykel Healthcare","idioma":"en","url_origen":"https://resources.fphcare.com/content/bubble-cpap-system-ui-185042847.pdf","descargada":"2026-10-02"}}$j$::jsonb
