UPDATE public.productos SET
  ficha_pdf = '/assets/productos/fichas/fisher-paykel-healthcare/bubble-cpap-system-ui-185042847.pdf',
  descripcion_larga_es = $d$El kit CPAP de burbuja BC161-10 es el sistema de Fisher & Paykel para ofrecer asistencia respiratoria a recién nacidos, manteniendo la expansión pulmonar cuando el alvéolo tiende a colapsarse. El BC161 se usa con la interfaz FlexiTrunk. La ficha del fabricante es el manual de instrucciones del sistema Bubble CPAP BC151/BC161: CPAP medio de 3 a 10 cmH₂O, flujo de entrada de 4 a 15 L/min, uso en UCIN/UCIP en neonatos de hasta 10 kg, componentes de un solo uso y duración máxima de 7 días.$d$,
  descripcion_larga_en = $d$The BC161-10 bubble CPAP kit is the Fisher & Paykel system to provide respiratory support to newborns, maintaining lung expansion when the alveolus tends to collapse. The BC161 is used with the FlexiTrunk interface. The manufacturer document is the Bubble CPAP System BC151/BC161 user instructions: mean CPAP of 3 to 10 cmH₂O, input flow of 4 to 15 L/min, for NICU/PICU use in neonates up to 10 kg, single-use components and a maximum use of 7 days.$d$,
  especificaciones = $j$[{"clave":"Fabricante","grupo":"Identificación","valor":"Fisher & Paykel Healthcare"},{"clave":"Documento","grupo":"Sistema","valor":"Instrucciones de uso Bubble CPAP BC151/BC161 (REF 185042847)"},{"clave":"CPAP medio","grupo":"Terapia","valor":"3 - 10 cmH₂O"},{"clave":"Flujo de entrada","grupo":"Terapia","valor":"4 - 15 L/min"},{"clave":"Duración / paciente","grupo":"Uso","valor":"Un solo paciente; máximo 7 días"},{"clave":"Modelo","grupo":"Identificación","valor":"BC161-10"},{"clave":"Fuga de gas a 60 cmH₂O","grupo":"Rendimiento","valor":"< 30 mL/min"}]$j$::jsonb,
  atributos = COALESCE(atributos, '{}'::jsonb) || $j${"beneficios_es":["Sistema BC161 diseñado para usarse con la interfaz FlexiTrunk.","CPAP medio de 3 a 10 cmH₂O con fuga de gas < 30 mL/min a 60 cmH₂O.","Humidificación > 33 mg/L en modo invasivo, según el fabricante."],"beneficios_en":["BC161 system designed to be used with the FlexiTrunk interface.","Mean CPAP of 3 to 10 cmH₂O with gas leakage < 30 mL/min at 60 cmH₂O.","Humidification > 33 mg/L in invasive mode, per the manufacturer."],"valor_es":"Un componente del sistema Bubble CPAP de Fisher & Paykel para soporte respiratorio neonatal, documentado en las instrucciones oficiales del sistema.","valor_en":"A component of the Fisher & Paykel Bubble CPAP system for neonatal respiratory support, documented in the official system instructions.","preguntas_frecuentes_es":[{"q":"¿Para qué pacientes es el sistema Bubble CPAP?","a":"Para neonatos y lactantes de hasta 10 kg que respiran espontáneamente y requieren CPAP, por ejemplo por prematuridad, en UCIN o UCIP, según las instrucciones del fabricante."},{"q":"¿Se puede reutilizar?","a":"No. Todos los componentes del sistema son de un solo paciente y el uso máximo indicado es de 7 días."},{"q":"¿Qué rango de CPAP maneja el sistema?","a":"CPAP medio de 3 a 10 cmH₂O con flujo de entrada de 4 a 15 L/min (inicial recomendado 6-8 L/min)."},{"q":"¿Dónde descargo la ficha técnica de Kit CPAP de Burbuja Ref BC161-10 Fisher & Paykel?","a":"En esta página, con el botón «Descargar ficha técnica»: es el PDF oficial de Fisher & Paykel Healthcare (en inglés)."}],"preguntas_frecuentes_en":[{"q":"Which patients is the Bubble CPAP system for?","a":"Spontaneously breathing neonates and infants up to 10 kg who need CPAP, for example due to prematurity, in NICU or PICU, per the manufacturer instructions."},{"q":"Can it be reused?","a":"No. All system components are single-patient use and the stated maximum use is 7 days."},{"q":"What CPAP range does the system provide?","a":"Mean CPAP of 3 to 10 cmH₂O with input flow of 4 to 15 L/min (recommended starting range 6-8 L/min)."},{"q":"Where can I download the Fisher & Paykel Bubble CPAP Kit Ref BC161-10 datasheet?","a":"On this page, with the “Download datasheet” button: it is the official Fisher & Paykel Healthcare PDF (in English)."}],"seo_keywords_es":["kit CPAP de burbuja BC161","CPAP de burbuja Fisher & Paykel","sistema CPAP neonatal","kit BC161-10","CPAP burbuja UCIN Colombia","instrucciones Bubble CPAP BC161"],"seo_keywords_en":["BC161 bubble CPAP kit","Fisher & Paykel bubble CPAP","neonatal CPAP system","BC161-10 kit","bubble CPAP NICU Colombia","Bubble CPAP BC161 instructions"],"ficha_fabricante":{"fabricante":"Fisher & Paykel Healthcare","idioma":"en","url_origen":"https://resources.fphcare.com/content/bubble-cpap-system-ui-185042847.pdf","descargada":"2026-10-02"}}$j$::jsonb
WHERE slug = 'kit-cpap-de-burbuja-ref-bc161-10-fisher-paykel';

UPDATE public.productos SET
  ficha_pdf = '/assets/productos/fichas/fisher-paykel-healthcare/bubble-cpap-system-ui-185042847.pdf',
  descripcion_larga_es = $d$El tubo nasal FlexiTrunk es la interfaz de Fisher & Paykel para administrar CPAP a recién nacidos, prematuros y lactantes, y se integra con prongs, máscaras y gorros de la misma línea. El sistema BC161 está diseñado para usarse con el FlexiTrunk. La ficha del fabricante es el manual de instrucciones del sistema Bubble CPAP BC151/BC161: CPAP medio de 3 a 10 cmH₂O, flujo de entrada de 4 a 15 L/min, uso en UCIN/UCIP en neonatos de hasta 10 kg, componentes de un solo uso y duración máxima de 7 días.$d$,
  descripcion_larga_en = $d$The FlexiTrunk nasal tube is the Fisher & Paykel interface to deliver CPAP to newborns, premature infants and infants, and integrates with prongs, masks and bonnets of the same line. The BC161 system is designed to be used with the FlexiTrunk. The manufacturer document is the Bubble CPAP System BC151/BC161 user instructions: mean CPAP of 3 to 10 cmH₂O, input flow of 4 to 15 L/min, for NICU/PICU use in neonates up to 10 kg, single-use components and a maximum use of 7 days.$d$,
