UPDATE public.productos SET
  ficha_pdf = '/assets/productos/fichas/fisher-paykel-healthcare/bubble-cpap-system-ui-185042847.pdf',
  descripcion_larga_es = $d$La máscara nasal para CPAP de burbuja ofrece presión positiva continua en neonatos con diseño ergonómico y varias tallas que ayudan a evitar zonas de presión por exceso de ajuste, y es una alternativa de descanso cuando se alterna con prongs. La ficha del fabricante es el manual de instrucciones del sistema Bubble CPAP BC151/BC161: CPAP medio de 3 a 10 cmH₂O, flujo de entrada de 4 a 15 L/min, uso en UCIN/UCIP en neonatos de hasta 10 kg, componentes de un solo uso y duración máxima de 7 días.$d$,
  descripcion_larga_en = $d$The bubble CPAP nasal mask provides continuous positive pressure in neonates with an ergonomic design and several sizes that help avoid pressure areas from over-tightening, and is a rest alternative when alternated with prongs. The manufacturer document is the Bubble CPAP System BC151/BC161 user instructions: mean CPAP of 3 to 10 cmH₂O, input flow of 4 to 15 L/min, for NICU/PICU use in neonates up to 10 kg, single-use components and a maximum use of 7 days.$d$,
  especificaciones = $j$[{"clave":"Fabricante","grupo":"Identificación","valor":"Fisher & Paykel Healthcare"},{"clave":"Documento","grupo":"Sistema","valor":"Instrucciones de uso Bubble CPAP BC151/BC161 (REF 185042847)"},{"clave":"CPAP medio","grupo":"Terapia","valor":"3 - 10 cmH₂O"},{"clave":"Flujo de entrada","grupo":"Terapia","valor":"4 - 15 L/min"},{"clave":"Duración / paciente","grupo":"Uso","valor":"Un solo paciente; máximo 7 días"}]$j$::jsonb,
