UPDATE public.productos SET
  ficha_pdf = '/assets/productos/fichas/fisher-paykel-healthcare/neopuff-resuscitation-mask-ui-185043891.pdf',
  descripcion_larga_es = $d$El kit de máscaras de reanimación Neopuff de Fisher & Paykel (RD800-EN) reúne la gama de tallas para pacientes neonatales desde prematuros: RD803 (XS, 35 mm, espacio muerto 13 mL), RD804 (S, 42 mm, 21 mL), RD805 (M, 50 mm, 34 mL), RD806 (L, 60 mm, 58 mL) y RD807 (XL, 72 mm, 97 mL). Son de un solo uso, se conectan a un circuito en T o a un dispositivo manual con conector de 15 mm y están diseñadas para sellar sobre nariz y boca.$d$,
  descripcion_larga_en = $d$The Fisher & Paykel Neopuff resuscitation mask kit (RD800-EN) brings together the size range for neonatal patients including premature infants: RD803 (XS, 35 mm, dead space 13 mL), RD804 (S, 42 mm, 21 mL), RD805 (M, 50 mm, 34 mL), RD806 (L, 60 mm, 58 mL) and RD807 (XL, 72 mm, 97 mL). They are single use, connect to a T-piece circuit or manual device with a 15 mm fitting and are designed to seal over the nose and mouth.$d$,
  especificaciones = $j$[{"clave":"Fabricante","grupo":"Identificación","valor":"Fisher & Paykel Healthcare"},{"clave":"Referencia","grupo":"Identificación","valor":"RD800-EN (kit); RD803-RD807"},{"clave":"Tallas y diámetro","grupo":"Tallas","valor":"RD803 XS 35 mm; RD804 S 42 mm; RD805 M 50 mm; RD806 L 60 mm; RD807 XL 72 mm"},{"clave":"Espacio muerto","grupo":"Tallas","valor":"13 mL (XS), 21 mL (S), 34 mL (M), 58 mL (L), 97 mL (XL)"},{"clave":"Duración / paciente","grupo":"Uso","valor":"Un solo uso; máximo 14 días"},{"clave":"Conector","grupo":"Conexión","valor":"15 mm macho"}]$j$::jsonb,
  atributos = COALESCE(atributos, '{}'::jsonb) || $j${"beneficios_es":["Cinco tallas (XS a XL) para ajustar la máscara desde prematuros.","Espacio muerto bajo documentado por talla, de 13 a 97 mL.","Un solo uso; se conecta a circuitos en T o a dispositivos manuales con conector de 15 mm."],"beneficios_en":["Five sizes (XS to XL) to fit from premature infants.","Low dead space documented by size, from 13 to 97 mL.","Single use; connects to T-piece circuits or manual devices with a 15 mm fitting."],"valor_es":"Un kit de iniciación con todas las tallas de máscara Neopuff, con especificaciones oficiales de Fisher & Paykel.","valor_en":"A starter kit with all Neopuff mask sizes, with official Fisher & Paykel specifications.","preguntas_frecuentes_es":[{"q":"¿Para qué pacientes es?","a":"Para neonatos y lactantes con insuficiencia respiratoria, en entorno hospitalario y por personal médico capacitado en reanimación infantil."},{"q":"¿Se puede reutilizar?","a":"No. Es de un solo uso: no se debe remojar, lavar ni esterilizar."},{"q":"¿Con qué se conecta?","a":"Con un conector cónico hembra de 15 mm (ISO 5356-1) de un circuito en T o un dispositivo de reanimación manual."},{"q":"¿Dónde descargo la ficha técnica de Kit de Máscaras Para Neopuff Ref RD800-EN Fisher & Paykel?","a":"En esta página, con el botón «Descargar ficha técnica»: es el PDF oficial de Fisher & Paykel Healthcare (en inglés)."}],"preguntas_frecuentes_en":[{"q":"Which patients is it for?","a":"Neonates and infants with respiratory insufficiency, in hospital settings and by medical staff trained in infant resuscitation."},{"q":"Can it be reused?","a":"No. It is single use: do not soak, wash or sterilise it."},{"q":"What does it connect to?","a":"A 15 mm conical female fitting (ISO 5356-1) of a T-piece circuit or a manual resuscitation device."},{"q":"Where can I download the Neopuff Mask Kit RD800-EN Fisher & Paykel datasheet?","a":"On this page, with the “Download datasheet” button: it is the official Fisher & Paykel Healthcare PDF (in English)."}],"seo_keywords_es":["kit de máscaras Neopuff","máscaras de reanimación neonatal","máscara de reanimación RD800","máscaras Fisher & Paykel","reanimación neonatal Colombia","ficha técnica máscara Neopuff"],"seo_keywords_en":["Neopuff mask kit","neonatal resuscitation masks","RD800 resuscitation mask","Fisher & Paykel masks","neonatal resuscitation Colombia","Neopuff mask datasheet"],"ficha_fabricante":{"fabricante":"Fisher & Paykel Healthcare","idioma":"en","url_origen":"https://resources.fphcare.com/content/neopuff-resuscitation-mask-ui-185043891.pdf","descargada":"2026-10-02"}}$j$::jsonb
WHERE slug = 'kit-de-mascaras-para-neopuff-ref-rd800-en-fisher-paykel';

UPDATE public.productos SET
  ficha_pdf = '/assets/productos/fichas/fisher-paykel-healthcare/neopuff-resuscitation-mask-ui-185043891.pdf',
  descripcion_larga_es = $d$La máscara de reanimación Neopuff de Fisher & Paykel es una interfaz de un solo uso para dar soporte ventilatorio a neonatos y lactantes con insuficiencia respiratoria. Se ofrece en cinco tallas (RD803 XS 35 mm a RD807 XL 72 mm), con espacio muerto de 13 a 97 mL, y se conecta con conector de 15 mm a un circuito en T o a un dispositivo manual. Debe usarla personal médico capacitado en reanimación infantil.$d$,
  descripcion_larga_en = $d$The Fisher & Paykel Neopuff resuscitation mask is a single-use interface to provide ventilatory support to neonates and infants with respiratory insufficiency. It is offered in five sizes (RD803 XS 35 mm to RD807 XL 72 mm), with dead space from 13 to 97 mL, and connects with a 15 mm fitting to a T-piece circuit or a manual device. It must be used by medical staff trained in infant resuscitation.$d$,
  especificaciones = $j$[{"clave":"Fabricante","grupo":"Identificación","valor":"Fisher & Paykel Healthcare"},{"clave":"Referencias","grupo":"Identificación","valor":"RD803-RD807"},{"clave":"Tallas y diámetro","grupo":"Tallas","valor":"RD803 XS 35 mm; RD804 S 42 mm; RD805 M 50 mm; RD806 L 60 mm; RD807 XL 72 mm"},{"clave":"Espacio muerto","grupo":"Tallas","valor":"13 mL (XS), 21 mL (S), 34 mL (M), 58 mL (L), 97 mL (XL)"},{"clave":"Duración / paciente","grupo":"Uso","valor":"Un solo uso; máximo 14 días"},{"clave":"Conector","grupo":"Conexión","valor":"15 mm macho"}]$j$::jsonb,
  atributos = COALESCE(atributos, '{}'::jsonb) || $j${"beneficios_es":["Interfaz de reanimación de un solo uso para neonatos y lactantes.","Cinco tallas con espacio muerto documentado de 13 a 97 mL.","Conexión de 15 mm compatible con circuitos en T y dispositivos manuales comunes."],"beneficios_en":["Single-use resuscitation interface for neonates and infants.","Five sizes with documented dead space from 13 to 97 mL.","15 mm connection compatible with T-piece circuits and common manual devices."],"valor_es":"Una máscara de reanimación neonatal en cinco tallas, con ficha oficial de Fisher & Paykel.","valor_en":"A neonatal resuscitation mask in five sizes, with official Fisher & Paykel datasheet.","preguntas_frecuentes_es":[{"q":"¿Para qué pacientes es?","a":"Para neonatos y lactantes con insuficiencia respiratoria, en entorno hospitalario y por personal médico capacitado en reanimación infantil."},{"q":"¿Se puede reutilizar?","a":"No. Es de un solo uso: no se debe remojar, lavar ni esterilizar."},{"q":"¿Con qué se conecta?","a":"Con un conector cónico hembra de 15 mm (ISO 5356-1) de un circuito en T o un dispositivo de reanimación manual."},{"q":"¿Dónde descargo la ficha técnica de Máscara Para Neopuff Desechable Fisher & Paykel?","a":"En esta página, con el botón «Descargar ficha técnica»: es el PDF oficial de Fisher & Paykel Healthcare (en inglés)."}],"preguntas_frecuentes_en":[{"q":"Which patients is it for?","a":"Neonates and infants with respiratory insufficiency, in hospital settings and by medical staff trained in infant resuscitation."},{"q":"Can it be reused?","a":"No. It is single use: do not soak, wash or sterilise it."},{"q":"What does it connect to?","a":"A 15 mm conical female fitting (ISO 5356-1) of a T-piece circuit or a manual resuscitation device."},{"q":"Where can I download the Fisher & Paykel Disposable Neopuff Mask datasheet?","a":"On this page, with the “Download datasheet” button: it is the official Fisher & Paykel Healthcare PDF (in English)."}],"seo_keywords_es":["máscara de reanimación neonatal Neopuff","máscara Neopuff desechable","máscara de reanimación para recién nacidos","máscara Fisher & Paykel","reanimación neonatal Colombia","ficha técnica máscara Neopuff"],"seo_keywords_en":["Neopuff neonatal resuscitation mask","disposable Neopuff mask","newborn resuscitation mask","Fisher & Paykel mask","neonatal resuscitation Colombia","Neopuff mask datasheet"],"ficha_fabricante":{"fabricante":"Fisher & Paykel Healthcare","idioma":"en","url_origen":"https://resources.fphcare.com/content/neopuff-resuscitation-mask-ui-185043891.pdf","descargada":"2026-10-02"}}$j$::jsonb
