UPDATE public.productos SET
  ficha_pdf = '/assets/productos/fichas/fisher-paykel-healthcare/neopuff-t-piece-circuit-rd1300-10-ui-185045725.pdf',
  descripcion_larga_es = $d$El circuito en T ergonómico Neopuff RD1300-10 de Fisher & Paykel es un circuito respiratorio de un solo uso que da soporte ventilatorio a neonatos y lactantes con insuficiencia respiratoria. Se conecta al reanimador Neopuff o a cualquier reanimador a gas conforme a ISO 10651-5, con un flujo de 5 a 15 L/min (8 L/min recomendado). Incorpora válvula PEEP, puerto de pico de pato integrado y otras funciones para uso hospitalario por personal médico capacitado.$d$,
  descripcion_larga_en = $d$The Fisher & Paykel Neopuff ergonomic T-piece circuit RD1300-10 is a single-use breathing circuit that provides ventilatory support to neonates and infants with respiratory insufficiency. It connects to the Neopuff resuscitator or any gas-powered resuscitator compliant with ISO 10651-5, with a flow of 5 to 15 L/min (8 L/min recommended). It includes a PEEP valve, an integrated duckbill port and other functions for hospital use by trained medical staff.$d$,
  especificaciones = $j$[{"clave":"Fabricante","grupo":"Identificación","valor":"Fisher & Paykel Healthcare"},{"clave":"Referencia","grupo":"Identificación","valor":"RD1300-10"},{"clave":"Flujo","grupo":"Uso","valor":"5 - 15 L/min (recomendado 8 L/min)"},{"clave":"Tipo","grupo":"Uso","valor":"Circuito en T de un solo uso"},{"clave":"Reanimadores","grupo":"Compatibilidad","valor":"Neopuff o a gas conforme a ISO 10651-5"}]$j$::jsonb,
  atributos = COALESCE(atributos, '{}'::jsonb) || $j${"beneficios_es":["Compatible con Neopuff y reanimadores a gas conformes a ISO 10651-5.","Válvula PEEP para seleccionar el nivel de presión espiratoria deseado.","Flujo de 5 a 15 L/min, con 8 L/min recomendado; un solo uso."],"beneficios_en":["Compatible with Neopuff and gas-powered resuscitators compliant with ISO 10651-5.","PEEP valve to select the desired expiratory pressure level.","Flow of 5 to 15 L/min, 8 L/min recommended; single use."],"valor_es":"Un circuito en T desechable para reanimación neonatal con válvula PEEP, con instrucciones oficiales de Fisher & Paykel.","valor_en":"A disposable T-piece circuit for neonatal resuscitation with PEEP valve, with official Fisher & Paykel instructions.","preguntas_frecuentes_es":[{"q":"¿Qué flujo se debe usar?","a":"Entre 5 y 15 L/min; el flujo recomendado es de 8 L/min y no debe usarse fuera de ese rango."},{"q":"¿Con qué reanimadores es compatible?","a":"Con el reanimador en T Neopuff o cualquier reanimador a gas conforme a ISO 10651-5."},{"q":"¿Qué debe haber disponible además?","a":"Un medio alternativo de reanimación sin gas, como una bolsa autoinflable, según las instrucciones."},{"q":"¿Dónde descargo la ficha técnica de Circuito Desechable Para Neopuff Ref RD1300-10 Fisher & Paykel?","a":"En esta página, con el botón «Descargar ficha técnica»: es el PDF oficial de Fisher & Paykel Healthcare (en inglés)."}],"preguntas_frecuentes_en":[{"q":"What flow should be used?","a":"Between 5 and 15 L/min; the recommended flow is 8 L/min and it must not be used outside that range."},{"q":"Which resuscitators is it compatible with?","a":"The Neopuff T-piece resuscitator or any gas-powered resuscitator compliant with ISO 10651-5."},{"q":"What else must be available?","a":"An alternative non-gas-powered means of resuscitation, such as a self-inflating bag, per the instructions."},{"q":"Where can I download the Disposable Circuit for Neopuff Ref RD1300-10 Fisher & Paykel datasheet?","a":"On this page, with the “Download datasheet” button: it is the official Fisher & Paykel Healthcare PDF (in English)."}],"seo_keywords_es":["circuito en T Neopuff","circuito de reanimación neonatal RD1300","circuito desechable Neopuff","circuito Fisher & Paykel","reanimación neonatal Colombia","instrucciones RD1300-10"],"seo_keywords_en":["Neopuff T-piece circuit","RD1300 neonatal resuscitation circuit","disposable Neopuff circuit","Fisher & Paykel circuit","neonatal resuscitation Colombia","RD1300-10 instructions"],"ficha_fabricante":{"fabricante":"Fisher & Paykel Healthcare","idioma":"en","url_origen":"https://resources.fphcare.com/content/neopuff-t-piece-circuit-rd1300-10-ui-185045725.pdf","descargada":"2026-10-02"}}$j$::jsonb
WHERE slug = 'circuito-desechable-para-neopuff-ref-rd1300-10-fisher-paykel';
